CREATE TABLE public.logos_transcript_exports (conversation_id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES public.profiles(id), export_date date NOT NULL, client_name text NOT NULL, file_id text, file_path text, format text, content_hash text, lease_token uuid, lease_until timestamptz, updated_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.logos_transcript_exports TO service_role; ALTER TABLE public.logos_transcript_exports ENABLE ROW LEVEL SECURITY; CREATE FUNCTION public.claim_logos_transcript_export(p_conversation_id text,p_user_id uuid,p_date date,p_client_name text,p_token uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.logos_transcript_exports; BEGIN INSERT INTO public.logos_transcript_exports(conversation_id,user_id,export_date,client_name) VALUES(p_conversation_id,p_user_id,p_date,p_client_name) ON CONFLICT DO NOTHING; SELECT * INTO r FROM public.logos_transcript_exports WHERE conversation_id=p_conversation_id FOR UPDATE; IF r.user_id<>p_user_id OR r.export_date<>p_date THEN RAISE EXCEPTION 'Conversation user/date mismatch'; END IF; IF r.lease_until>now() THEN RETURN jsonb_build_object('claimed',false); END IF; UPDATE public.logos_transcript_exports SET lease_token=p_token,lease_until=now()+interval '3 minutes',updated_at=now() WHERE conversation_id=p_conversation_id; RETURN to_jsonb(r)||jsonb_build_object('claimed',true); END; $$; REVOKE ALL ON FUNCTION public.claim_logos_transcript_export(text,uuid,date,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_logos_transcript_export(text,uuid,date,text,uuid) TO service_role;